function useDrag(handle: HTMLElement, onMove: (x: number) => void) {
  const down = (e: PointerEvent) => {
    e.preventDefault();
    handle.addEventListener('pointermove', move);
  };

  const move = (e: PointerEvent) => {
    e.preventDefault();
    onMove(e.clientX);
  };

  const up = (e: PointerEvent) => {
    handle.removeEventListener('pointermove', move);
  };

  handle.addEventListener('pointerdown', down);
  handle.addEventListener('pointerup', up);

  return () => {
    handle.removeEventListener('pointerdown', down);
    handle.removeEventListener('pointerup', up);
  };
}

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  if (url.pathname.startsWith('/api/')) {
    event.respondWith(
      caches.open('v1').then((cache) =>
        cache.match(event.request).then((cached) =>
          cached ||
          fetch(event.request).then((res) => {
            cache.put(event.request, res.clone());
            return res;
          })
        )
      )
    );
  }
});

self.addEventListener('sync', (event) => {
  if (event.tag === 'outbox') {
    event.waitUntil(
      (async () => {
        const outbox: Op[] = await idb.get('outbox');
        for (const op of outbox) {
          await fetch(op.url, {
            method: 'POST',
            body: JSON.stringify(op.body),
          });
          await idb.remove(op.id);
        }
      })()
    );
  }
});

export function ProductGrid({ products }: { products: Product[] }) {
  return (
    <div className="grid">
      {products.map((p) => (
        <a key={p.id} href={`/p/${p.id}`} className="card">
          <img src={p.image} width="960" height="720" alt={p.name} />
          <h3>{p.name}</h3>
        </a>
      ))}
    </div>
  );
}

export function CheckoutForm({ onPay }: { onPay: (data: FormData) => void }) {
  const [error, setError] = useState<string | null>(null);
  const [keyboardOpen, setKeyboardOpen] = useState(false);

  useEffect(() => {
    const onResize = () => {
      setKeyboardOpen(window.innerHeight < window.screen.height - 150);
    };
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  return (
    <div className="checkout">
      <header style={{ position: 'fixed', top: 0, left: 0, right: 0, height: 72 }}>
        Checkout
      </header>
      {error && <p className="error">{error}</p>}
      <form
        style={{ paddingTop: 72, paddingBottom: keyboardOpen ? 320 : 96 }}
        onSubmit={(event) => {
          event.preventDefault();
          onPay(new FormData(event.currentTarget));
        }}
      >
        <input name="card" placeholder="Card number" inputMode="numeric" />
        <input name="phone" placeholder="Phone number" />
        <input name="email" placeholder="Email" />
        <div style={{ position: 'fixed', bottom: 0, left: 0, right: 0 }}>
          <button type="submit">Pay</button>
        </div>
      </form>
    </div>
  );
}
